mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g1-3/bot.mjs';
import assert from 'node:assert/strict';

const phone = '+13125550142';
const u = (timezone) => ({ id: 'u_1', phone, timezone });
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

// Helper: at the returned nextAllowedAt the gate must allow; 1 ms earlier it must not.
function assertExactReopen(user, now) {
  const r = checkSms(user, now);
  assert.equal(r.allowed, false);
  assert.ok(r.nextAllowedAt instanceof Date);
  assert.ok(r.nextAllowedAt.getTime() > now.getTime(), 'nextAllowedAt must be after now');
  assert.equal(checkSms(user, r.nextAllowedAt).allowed, true, 'allowed exactly at nextAllowedAt');
  const before = new Date(r.nextAllowedAt.getTime() - 1);
  assert.equal(checkSms(user, before).allowed, false, 'not allowed 1ms before nextAllowedAt');
  return r;
}

ok('Chicago 10:00 local (15:00Z in CDT) allowed', () => {
  const r = checkSms(u('America/Chicago'), at('2026-10-23T15:00:00Z'));
  assert.deepEqual(r, { allowed: true, reason: r.reason, nextAllowedAt: null });
});

ok('Chicago 07:59 local held until 08:00 local same day', () => {
  // 07:59 CDT (UTC-5) = 12:59Z ; 08:00 CDT = 13:00Z
  const r = assertExactReopen(u('America/Chicago'), at('2026-10-23T12:59:00Z'));
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');
});

ok('Chicago 19:59:59 allowed, 20:00:00 held until next morning', () => {
  assert.equal(checkSms(u('America/Chicago'), at('2026-10-24T00:59:59Z')).allowed, true);  // 19:59:59 CDT
  const r = assertExactReopen(u('America/Chicago'), at('2026-10-24T01:00:00Z'));          // 20:00 CDT
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-24T13:00:00.000Z');                 // 08:00 CDT Oct 24
});

ok('Istanbul (UTC+3, no DST) 08:00 exact boundary allowed', () => {
  assert.equal(checkSms(u('Europe/Istanbul'), at('2026-10-23T05:00:00Z')).allowed, true);
  assertExactReopen(u('Europe/Istanbul'), at('2026-10-23T04:59:59Z'));
});

ok('Kolkata half-hour offset (+05:30): 08:00 IST = 02:30Z', () => {
  const r = assertExactReopen(u('Asia/Kolkata'), at('2026-10-23T02:29:00Z'));
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T02:30:00.000Z');
  assert.equal(checkSms(u('Asia/Kolkata'), at('2026-10-23T02:30:00Z')).allowed, true);
});

ok('Adelaide half-hour offset (+10:30 in October, DST on): 20:00 local boundary', () => {
  // 19:59 ACDT (UTC+10:30) = 09:29Z allowed; 20:00 = 09:30Z held
  assert.equal(checkSms(u('Australia/Adelaide'), at('2026-10-23T09:29:00Z')).allowed, true);
  assertExactReopen(u('Australia/Adelaide'), at('2026-10-23T09:30:00Z'));
});

ok('Chicago DST spring-forward day (2026-03-08): 08:00 CDT = 13:00Z', () => {
  const r = assertExactReopen(u('America/Chicago'), at('2026-03-08T06:00:00Z')); // 00:00 CST
  assert.equal(r.nextAllowedAt.toISOString(), '2026-03-08T13:00:00.000Z');       // 08:00 CDT
});

ok('Chicago DST fall-back day (2026-11-01): 08:00 CST = 14:00Z', () => {
  const r = assertExactReopen(u('America/Chicago'), at('2026-11-01T05:00:00Z')); // 00:00 CDT
  assert.equal(r.nextAllowedAt.toISOString(), '2026-11-01T14:00:00.000Z');       // 08:00 CST
});

ok('Late-night in UTC-far zone rolls to next calendar day (Honolulu 23:00 HST)', () => {
  // 23:00 HST (UTC-10) = 09:00Z next day; 08:00 HST next day = 18:00Z
  const r = assertExactReopen(u('Pacific/Honolulu'), at('2026-10-24T09:00:00Z'));
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-25T18:00:00.000Z');
});

ok('Month boundary: Oct 31 23:00 in New_York rolls to Nov 1 08:00 EST', () => {
  // 23:00 EDT Oct 31 = 03:00Z Nov 1 ; 08:00 on Nov 1 EST(after fall-back Nov 1 2026 2am) = 13:00Z
  const r = assertExactReopen(u('America/New_York'), at('2026-11-01T03:00:00Z'));
  assert.equal(r.nextAllowedAt.toISOString(), '2026-11-01T13:00:00.000Z');
});

ok('null timezone -> held, nextAllowedAt null', () => {
  const r = checkSms(u(null), at('2026-10-23T15:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt, null);
  assert.match(r.reason, /no valid time zone/);
});

ok('unrecognised timezone -> held, nextAllowedAt null', () => {
  for (const tz of ['Mars/Olympus', 'Chicago', '', ' America/Chicago', 42, undefined]) {
    const r = checkSms(u(tz), at('2026-10-23T15:00:00Z'));
    assert.equal(r.allowed, false, String(tz));
    assert.equal(r.nextAllowedAt, null, String(tz));
  }
});

ok('lowercase IANA name is accepted by Intl and gives correct window', () => {
  assert.equal(checkSms(u('america/chicago'), at('2026-10-23T15:00:00Z')).allowed, true);
});

ok('bad phone -> held, nextAllowedAt null', () => {
  const r = checkSms({ id: 'x', phone: '3125550142', timezone: 'America/Chicago' }, at('2026-10-23T15:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt, null);
});

ok('invalid now throws', () => {
  assert.throws(() => checkSms(u('America/Chicago'), new Date('nope')), TypeError);
  assert.throws(() => checkSms(u('America/Chicago'), '2026-10-23'), TypeError);
});

ok('does not depend on machine TZ: same result under TZ=Asia/Tokyo and TZ=Pacific/Kiritimati', () => {
  // Run in child processes below; here just confirm the result is stable in this process.
  const a = checkSms(u('America/Chicago'), at('2026-10-23T12:59:00Z'));
  assert.equal(a.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');
});

console.log(`\n${n} groups passed`);
